import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 56 What do they usually do?","description":"学习 一般现在时的习惯动作，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 56 What do they usually do?","description":"学习 一般现在时的习惯动作，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 一般现在时的习惯动作，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 55 The Sawyer family","link":"/life/english/new-concept/book-1/unit-03/lesson-055"},"next":{"text":"第一册：英语初阶 · Lesson 57 An unusual day","link":"/life/english/new-concept/book-1/unit-03/lesson-057"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 55 The Sawyer family","link":"/life/english/new-concept/book-1/unit-03/lesson-055"},"next":{"text":"第一册：英语初阶 · Lesson 57 An unusual day","link":"/life/english/new-concept/book-1/unit-03/lesson-057"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-056.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-056.md"}'),l={name:"life/english/new-concept/book-1/unit-03/lesson-056.md"};function i(s,e,r,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-56-what-do-they-usually-do" tabindex="-1">第一册：英语初阶 · Lesson 56 What do they usually do? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-56-what-do-they-usually-do" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 56 What do they usually do?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-055">配套课 Lesson 55</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>介绍一家人的每日作息 本课要掌握一般现在时的习惯动作，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>family</td><td>/ˈfæməli/</td><td>n.</td><td>家庭</td><td>a large family</td></tr><tr><td>usually</td><td>/ˈjuːʒuəli/</td><td>adv.</td><td>通常</td><td>usually cook</td></tr><tr><td>arrive</td><td>/əˈraɪv/</td><td>v.</td><td>到达</td><td>arrive home</td></tr><tr><td>together</td><td>/təˈɡeðə/</td><td>adv.</td><td>一起</td><td>eat together</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>every morning — 每天早晨</li><li>arrive home — 到家，home 前不加 at</li></ul><h2 id="语法讲解-一般现在时的习惯动作" tabindex="-1">语法讲解：一般现在时的习惯动作 <a class="header-anchor" href="#语法讲解-一般现在时的习惯动作" aria-label="Permalink to &quot;语法讲解：一般现在时的习惯动作&quot;">​</a></h2><p>一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We usually cook dinner together.</p></blockquote><p>我们通常一起做晚饭。</p><p>We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>单数 father 对应 leaves，不能因为句中有 my 就用第一人称形式。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“We usually cook dinner together.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We usually cook dinner together. My father leaves home at half past seven.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“介绍一家人的每日作息”写两至三句，再读给同伴听。至少使用一次一般现在时的习惯动作，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。 My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 at/in：___ half past seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 按本课规则判断：一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我们通常一起做晚饭。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We usually cook dinner together.</p><p><strong>解析：</strong> We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：My father leaves home at half past seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我父亲每天七点半离家。</p><p><strong>解析：</strong> My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时的习惯动作。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-055">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-057">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(l,[["render",i]]);export{p as __pageData,f as default};
